// The Khmer letters of the fonts the 🖼 images use (Google Fonts' Khmer subsets,
// SIL Open Font License), built into the page so Cloudflare's browser doesn't
// fetch them for every picture. Latin text uses the browser's own fonts.
// Made from fonts.gstatic.com woff2 files: Battambang 400/700, Moul, Noto Sans Khmer.
export const FONT_CSS = [
  `@font-face { font-family: 'Battambang'; font-weight: 400; font-style: normal; font-display: block; unicode-range: U+1780-17FF, U+19E0-19FF, U+200C-200D, U+25CC; src: url(data:font/woff2;base64,) format('woff2'); }`,
  `@font-face { font-family: 'Battambang'; font-weight: 700; font-style: normal; font-display: block; unicode-range: U+1780-17FF, U+19E0-19FF, U+200C-200D, U+25CC; src: url(data:font/woff2;base64,) format('woff2'); }`,
  `@font-face { font-family: 'Moul'; font-weight: 400; font-style: normal; font-display: block; unicode-range: U+1780-17FF, U+19E0-19FF, U+200C-200D, U+25CC; src: url(data:font/woff2;base64,) format('woff2'); }`,
  `@font-face { font-family: 'Noto Sans Khmer'; font-weight: 400; font-style: normal; font-display: block; unicode-range: U+1780-17FF, U+19E0-19FF, U+200C-200D, U+25CC; src: url(data:font/woff2;base64,) format('woff2'); }`,
].join('\n');
